import threading
import time

def throttle(func):
    """
    Decorator to throttle a function to at most one execution per minute.

    Usage:
    @throttle
    def my_job():
        print("Running periodic task...")
    """
    last_time = 0
    lock = threading.Lock()

    def wrapper(*args, **kwargs):
        nonlocal last_time
        with lock:
            current_time = time.time()
            if current_time - last_time >= 60:
                last_time = current_time
                return func(*args, **kwargs)
            else:
                return None  # Skip execution; only one allowed per minute

    return wrapper

@throttle(60)
def process_job():
    """This function will execute at most once per minute."""
    print("Job started at", time.ctime())
    # Simulate job processing
    time.sleep(5)
    print("Job completed at", time.ctime())

# Test the throttling by calling it consecutively
def test_throttling():
    for _ in range(4):
        process_job()
        time.sleep(25)  # Sleep less than 60 to test throttling

