import click
import os
import zipfile
import tarfile

@click.command()
@click.argument("archive_path")
@click.option(
    "--dest",
    default=".",
    help="Destination directory to extract to (default is current directory).",
)
def extract(archive_path, dest):
    """
    Decompress an archive and list its contents.
    """
    if not os.path.exists(archive_path):
        click.echo(f"Error: Archive file not found: {archive_path}", err=True)
        return

    if not os.path.isfile(archive_path):
        click.echo(f"Error: {archive_path} is not a file.", err=True)
        return

    if os.path.exists(dest) and os.path.isfile(dest):
        click.echo(f"Error: {dest} is a file, but a directory is expected.", err=True)
        return

    try:
        os.makedirs(dest, exist_ok=True)
    except Exception as e:
        click.echo(f"Error creating destination directory {dest}: {e}", err=True)
        return

    try:
        if archive_path.endswith(".zip"):
            with zipfile.ZipFile(archive_path, "r") as zipf:
                zipf.extractall(dest)
        elif archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
            with tarfile.open(archive_path, "r:gz") as tarf:
                tarf.extractall(dest)
        elif archive_path.endswith(".tar"):
            with tarfile.open(archive_path, "r:") as tarf:
                tarf.extractall(dest)
        else:
            click.echo(f"Unsupported archive type: {archive_path}", err=True)
            return
    except Exception as e:
        click.echo(f"Error extracting archive: {e}", err=True)
        return

    try:
        files = os.listdir(dest)
        click.echo(f"Extracted {len(files)} item(s) to {dest}:")
        for file in files:
            click.echo(f" - {file}")
    except Exception as e:
        click.echo(f"Error listing extracted files: {e}", err=True)
        return

