import click
import os
import zipfile
import tarfile

@click.command()
@click.argument('file_path', type=click.Path(exists=True))
@click.option('--output', '-o', default='.', help='Directory to extract files into.', type=click.Path(file_okay=False, dir_okay=True, exists=False))
def decompress(file_path, output):
    """Decompress an archive file to the specified directory."""
    try:
        os.makedirs(output, exist_ok=True)
        _, ext = os.path.splitext(file_path)
        ext = ext.lower()

        if ext == '.zip':
            with zipfile.ZipFile(file_path, 'r') as zip_ref:
                zip_ref.extractall(output)
                members = zip_ref.namelist()
                click.echo(f"Extracted {len(members)} files from {file_path} to {output}")
                for member in members:
                    click.echo(f" - {member}")
        elif ext in ('.tar', '.tgz', '.tar.gz'):
            with tarfile.open(file_path, 'r:*') as tar_ref:
                tar_ref.extractall(output)
                members = tar_ref.getmembers()
                click.echo(f"Extracted {len(members)} files from {file_path} to {output}")
                for member in members:
                    click.echo(f" - {member.name}")
        else:
            click.echo(f"Unsupported archive type: {ext}")

    except Exception as e:
        click.echo(f"Error decompressing {file_path}: {e}", err=True)
        raise click.exceptions.ClickException(f"Decompression failed: {str(e)}")

