def main():
    # Read the input line from standard input
    input_line = sys.stdin.read().strip()
    labels = input_line.split()

    if not labels:
        return  # Handle empty input gracefully

    # Step 1: Determine unique categories in the order of first occurrence
    unique_order = []
    for label in labels:
        if label not in unique_order:
            unique_order.append(label)

    # Step 2: Create a mapping from label to its index
    label_to_index = {label: idx for idx, label in enumerate(unique_order)}

    # Step 3: Generate the one-hot encoded matrix
    matrix = []
    for label in labels:
        row = [0] * len(unique_order)
        row[label_to_index[label]] = 1
        matrix.append(row)

    # Step 4: Output the matrix
    for row in matrix:
        print(' '.join(map(str, row)))

