import subprocess
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import time

def watch_file(file_path, command):
    class FileChangeHandler(FileSystemEventHandler):
        def on_modified(self, event):
            if event.src_path == file_path:
                print(f"File {file_path} changed. Running command: {command}")
                subprocess.run(command, shell=True)

    observer = Observer()
    observer.schedule(FileChangeHandler(), path=".", recursive=False)
    print(f"Watching {file_path} for changes... (Press Ctrl+C to stop)")
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
        observer.join()

