import os
import time
from toolbox.utils import import_string
import click

def watchfile(file_path, callback_str):
    """
    Watch for changes in a file and trigger a Python callback function on modification.
    """
    try:
        callback = import_string(callback_str)
    except (ValueError, ImportError, AttributeError) as e:
        click.echo(f"Error importing callback '{callback_str}': {e}")
        return

    click.echo(f"Started watching '{file_path}' for changes. Callback: {callback_str}")

    try:
        last_modified = os.path.getmtime(file_path)
        while True:
            time.sleep(1)
            current_modified = os.path.getmtime(file_path)
            if current_modified > last_modified:
                click.echo(f"File modified at {time.ctime(current_modified)}, triggering callback...")
                try:
                    callback()
                except Exception as e:
                    click.echo(f"Callback failed: {e}")
                last_modified = current_modified
    except KeyboardInterrupt:
        click.echo("Watchfile stopped by user.")
    except Exception as e:
        click.echo(f"Error in file watcher: {e}")

