import math
import argparse

def distance(p1, p2):
    """Computes the Euclidean distance between two points (p1 and p2)."""
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def get_neighbors(point, radius, points):
    """Finds all indices of points within the `radius` from the given `point`."""
    neighbors = []
    for idx, p in enumerate(points):
        if distance(point, p) <= radius:
            neighbors.append(idx)
    return neighbors

def main():
    # Parse command-line arguments
    parser = argparse.ArgumentParser(description="Cluster 2D points by density using DBSCAN-like logic.")
    parser.add_argument('radius', type=float, help='Radius (epsilon) for neighbor search')
    parser.add_argument('min_size', type=int, help='Minimum number of points to form a cluster')
    args = parser.parse_args()

    # Read input points from standard input
    points = []
    for line in sys.stdin:
        if line.strip():
            x, y = map(float, line.strip().split())
            points.append((x, y))

    n = len(points)
    visited = set()
    labels = [-1] * n  # -1 denotes noise
    cluster_id = 0

    for i in range(n):
        if i not in visited:
            neighbors = get_neighbors(points[i], args.radius, points)
            if len(neighbors) < args.min_size:
                continue  # Not enough neighbors to form a cluster
            else:
                labels[i] = cluster_id
                visited.add(i)
                queue = [i]
                while queue:
                    current_idx = queue.pop(0)
                    for neighbor_idx in get_neighbors(points[current_idx], args.radius, points):
                        if neighbor_idx not in visited:
                            visited.add(neighbor_idx)
                            labels[neighbor_idx] = cluster_id
                            queue.append(neighbor_idx)
                cluster_id += 1

    # Output the cluster ID for each point, in order of input
    for label in labels:
        print(label)

if __name__ == '__main__':
    main()

