import html.parser

class LinkExtractor(html.parser.HTMLParser):
    """Custom HTML parser to extract all <a href> links from HTML content."""

    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for name, value in attrs:
                if name.lower() == 'href':
                    self.links.append(value)

def extract_links(html_content: str) -> list:
    """
    Extract all href attributes from <a> tags in the given HTML content.

    :param html_content: A string containing HTML content.
    :return: A list of URL strings (hrefs) from <a> tags.
    """
    parser = LinkExtractor()
    parser.feed(html_content)
    return parser.links

