@click.command()
@click.argument('source')
def extract_links_command(source: str):
    """
    CLI tool to extract all links from an HTML page.

    If the source starts with 'http://', it's treated as a URL.
    Otherwise, it's treated as a local file path.
    """
    try:
        if source.startswith('http://') or source.startswith('https://'):
            # Fetch content from URL
            with urllib.request.urlopen(source) as response:
                html_content = response.read().decode('utf-8')

        elif os.path.exists(source):
            # Read content from file
            with open(source, 'r', encoding='utf-8') as file:
                html_content = file.read()

        else:
            click.echo(f"Invalid source `{source}`. Please provide a valid URL or a local file path.")
            return

        links = extract_links(html_content)
        for link in links:
            click.echo(link)

    except Exception as e:
        click.echo(f"Error: {e}", err=True)

