    {'group': 'A', 'value': 1},
    {'group': 'A', 'value': 2},
    {'group': 'B', 'value': 3},
    {'group': 'B', 'value': 4}
]

from collections import defaultdict

def standardize_within_group(records, value_col, group_col):
    groups = defaultdict(list)
    for record in records:
        group = record[group_col]
        groups[group].append(record)

    for group_key, group_records in groups.items():
        values = [record[value_col] for record in group_records]
        n = len(values)
        if n == 0:
            continue

        mean = sum(values) / n
        sum_sq_diff = sum((x - mean)**2 for x in values)
        variance = sum_sq_diff / n
        std = variance ** 0.5

        if std == 0:
            for record in group_records:
                record[value_col] = 0.0
        else:
            for record in group_records:
                z_score = (record[value_col] - mean) / std
                record[value_col] = z_score

    return records

