def watch_file(
    path: str | Path,
    callback: callable,
    interval: float = 1.0,
) -> None:
    """Watch a file for changes and call the callback when it changes.

    The function runs indefinitely, checking the file's modification time every `interval` seconds.
    When a change is detected, the callback is invoked with the file path as an argument.
    """
    path = Path(path)
    last_modified = path.stat().st_mtime

    while True:
        time.sleep(interval)
        try:
            current_modified = path.stat().st_mtime
        except FileNotFoundError:
            # File was deleted; exit the watcher
            break
        if current_modified != last_modified:
            callback(path)
            last_modified = current_modified

