def watch_file(
    path: str | Path,
    callback: Callable[[Path], None],
    interval: float = 1.0,
) -> None:
    """Watch a file for changes and call the callback when it changes.

    The file is checked for modifications at regular intervals.
    If it changes, the provided callback is invoked with the file path.
    """
    path = Path(path)
    last_modified = path.stat().st_mtime
    while True:
        time.sleep(interval)
        try:
            current_modified = path.stat().st_mtime
        except FileNotFoundError:
            continue
        if current_modified != last_modified:
            callback(path)
            last_modified = current_modified

