from collections import defaultdict
import argparse
import sys


def bucket_hour(args):
    # 1. Read input from file or stdin
    if args.file:
        input_text = args.file.read()
    else:
        input_text = sys.stdin.read()

    # 2. Parse timestamps from input (ISO format assumed)
    timestamps = []
    for line in input_text.strip().splitlines():
        try:
            dt = datetime.fromisoformat(line.strip())
            timestamps.append(dt)
        except ValueError:
            print(f"Skipping invalid timestamp: {line}", file=sys.stderr)

    # 3. Determine the target timezone to use
    if args.timezone:
        try:
            tz = ZoneInfo(args.timezone)
        except Exception as e:
            print(f"Invalid timezone: {args.timezone}", file=sys.stderr)
            return
    else:
        # If no timezone provided, use the system local time
        tz = datetime.now(ZoneInfo("UTC")).astimezone().tzinfo

    # 4. Bucket timestamps by hour in the specified timezone
    grouped = defaultdict(list)
    for ts in timestamps:
        # Handle naive or unaware datetime
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=tz)
        else:
            ts = ts.astimezone(tz)
        hour = ts.hour
        grouped[hour].append(ts)

    # 5. Output the result
    for hour in sorted(grouped.keys()):
        count = len(grouped[hour])
        print(f"Hour {hour}: {count} timestamps")

