import sys

@click.command()
@click.option('--input-file', required=True, help='Path to the input file with timestamps in ISO 8601 format.')
@click.option('--timezone', default=None, help='Optional: Timezone to interpret the timestamps in (e.g., America/New_York). Defaults to local time.')
def bucket_hour(input_file, timezone):
    """
    Bucket timestamps by their local hour of day.
    """
    try:
        if timezone:
            tz = ZoneInfo(timezone)
        else:
            tz = tzlocal()
    except ZoneInfoNotFoundError:
        click.echo(f"Invalid timezone: {timezone}", err=True)
        return

    try:
        with open(input_file, 'r') as file:
            timestamps = [line.strip() for line in file if line.strip()]
    except FileNotFoundError:
        click.echo(f"Input file not found: {input_file}", err=True)
        return

    hourly_buckets = {}

    for ts_str in timestamps:
        try:
            dt_naive = datetime.fromisoformat(ts_str)
        except ValueError:
            click.echo(f"Invalid timestamp format: {ts_str}", err=True)
            continue

        # Localize the naive datetime to the specified timezone
        dt = dt_naive.replace(tzinfo=tz)

        hour = dt.hour

        if hour in hourly_buckets:
            hourly_buckets[hour] += 1
        else:
            hourly_buckets[hour] = 1

    for hour, count in sorted(hourly_buckets.items()):
        click.echo(f"{hour}: {count}")

