            counts = defaultdict(int)
            for p in factors:
                counts[p] += 1

            # Step 5: Prepare the output
            primes = sorted(counts.keys())
            result = ''

            for i, p in enumerate(primes):
                if i > 0:
                    result += ' * '
                if counts[p] == 1:
                    result += str(p)
                else:
                    result += f"{p}^{counts[p]}"
