import sys

def prime_factorization(n):
    if n == 0:
        return '0'
    n_abs = abs(n)
    if n_abs < 2:
        return '1'

    factors = []
    i = 2
    while i * i <= n_abs:
        while n_abs % i == 0:
            factors.append(i)
            n_abs //= i
        i += 1
    if n_abs > 1:
        factors.append(n_abs)

    if not factors:
        return '1'

    prev = factors[0]
    count = 1
    exponents = []
    for num in factors[1:]:
        if num == prev:
            count += 1
        else:
            exponents.append((prev, count))
            prev = num
            count = 1
    exponents.append((prev, count))

    parts = []
    for prime, exp in exponents:
        if exp == 1:
            parts.append(f"{prime}")
        else:
            parts.append(f"{prime}^{exp}")

    return '*'.join(parts)

