import sys

def prime_factors(n):
    """
    Returns the list of prime factors of a positive integer using trial division.
    """
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

