    grouped.append((current, count))  # Add the last group

    # Format the output
    result = []
    for prime, exponent in grouped:
        if exponent == 1:
            result.append(str(prime))
        else:
            result.append(f"{prime}^{exponent}")

    print(" * ".join(result))

