import sys

def prime_factorization(n):
    factors = []
    if n == 1:
        return factors
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def main():
    try:
        n = int(sys.stdin.read().strip())
        n = abs(n)
        factors = prime_factorization(n)
        if factors:
            print(' '.join(map(str, factors)))
    except ValueError:
        print("Error: Input must be an integer.")

