import sys
from statistics import mean, stdev, StatisticsError

def main():
    # Read all lines from standard input
    input_lines = [line.strip() for line in sys.stdin if line.strip()]

    # Store data as (group_key, value) tuples
    data = []
    for line in input_lines:
        if ',' not in line:
            continue  # Skip if line is malformed
        group, value = line.split(',', 1)
        try:
            value = float(value.strip())
            data.append((group, value))
        except ValueError:
            continue  # Skip non-convertible values

    # Group by group key
    group_dict = {}
    for group_key, value in data:
        if group_key not in group_dict:
            group_dict[group_key] = []
        group_dict[group_key].append(value)

    # Compute mean and standard deviation for each group
    group_stats = {}
    for group_key, values in group_dict.items():
        mean_val = mean(values)
        if len(values) == 1:
            std_val = 0.0
        else:
            try:
                std_val = stdev(values)
            except StatisticsError:
                std_val = 0.0
        group_stats[group_key] = (mean_val, std_val)

    # Standardize the values for each entry
    standardized_data = []
    for group_key, value in data:
        mean_val, std_val = group_stats[group_key]
        if std_val == 0.0:
            standardized = 0.0  # Handle division by zero
        else:
            standardized = (value - mean_val) / std_val
        standardized_data.append((group_key, standardized))

    # Output the standardized values
    for group_key, standardized in standardized_data:
        print(f"{group_key},{standardized}")

