def topological_sort(dependencies):
    # Step 1: Collect all unique nodes (tasks)
    nodes = set()
    for u, v in dependencies:
        nodes.add(u)
        nodes.add(v)

    # Step 2: Initialize graph and in-degree dictionary
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Step 3: Fill the graph and in-degree counts based on dependencies
    for u, v in dependencies:
        graph[u].append(v)
        in_degree[v] += 1

    # Step 4: Initialize queue with nodes that have no dependencies
    queue = deque()
    for node in in_degree:
        if in_degree[node] == 0:
            queue.append(node)

    # Step 5: Process the nodes and build the topological order
    result = []
    while queue:
        current = queue.popleft()
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 6: Check for cycles (and return empty list if detected)
    if len(result) != len(nodes):
        return []

    return result

