import sys
import gzip
import bz2
import zipfile
import io

def decompress_data(data):
    """Try to decompress the input data based on its format."""
    if data.startswith(b'\x1f\x8b'):
        return gzip.decompress(data)
    elif data.startswith(b'BZh'):
        return bz2.decompress(data)
    elif data.startswith(b'PK\x03\x04'):
        with zipfile.ZipFile(io.BytesIO(data), 'r') as zip_ref:
            # Extract the first file
            zip_info = zip_ref.infolist()[0]
            with zip_ref.open(zip_info) as f:
                return f.read()
    else:
        # Assume the data is not compressed
        return data

def main():
    # Read the entire input as bytes
    compressed_data = sys.stdin.buffer.read()

    try:
        # Decompress the data
        decompressed_data = decompress_data(compressed_data)
    except Exception as e:
        # Handle errors gracefully if the data is not as expected
        print(f"Decompression failed: {e}", file=sys.stderr)
        sys.exit(1)

    # Write the decompressed data to stdout (binary mode)
    sys.stdout.buffer.write(decompressed_data)

if __name__ == '__main__':
    main()

import os
import time
import threading

def watch_file(file_path, callback):
    def check_changes():
        try:
            # Initial check for valid access to the file
            last_modified = os.path.getmtime(file_path)
        except (OSError, IOError) as e:
            print(f"Error accessing file '{file_path}': {e}")
            return

        while True:
            try:
                time.sleep(1)  # Poll every 1 second
                current_modified = os.path.getmtime(file_path)
            except (OSError, IOError) as e:
                print(f"Error accessing file '{file_path}': {e}")
                break

            if current_modified != last_modified:
                callback()
                last_modified = current_modified

    # Run the change checking in the background
    thread = threading.Thread(target=check_changes)
    thread.daemon = True  # So it exits when the main program exits
    thread.start()

