        log_level = parts[2]
        message = ' '.join(parts[3:])

        try:
            dt = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            continue  # Invalid timestamp format

        structured = {
            'timestamp': dt.isoformat(),
            'log_level': log_level,
            'message': message
