import re
import sys
import json

def main():
    # Regular expression pattern to match log lines
    pattern = re.compile(
        r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) '  # timestamp: YYYY-MM-DD HH:MM:SS
        r'([A-Z]+): '                              # log level: uppercase string
        r'(.*)$'                                   # message: the rest of the line
    )

    for line in sys.stdin:
        line = line.rstrip('\n')
        match = pattern.match(line)
        if match:
            timestamp, level, message = match.groups()
            structured = {
                "timestamp": timestamp,
                "level": level,
                "message": message
            }
            print(json.dumps(structured))

