def count_timestamps_by_hour(
    timestamps: List[datetime.datetime],
) -> Dict[int, int]:
    """Count the number of timestamps per local hour of the day.

    Args:
        timestamps: List of datetime objects representing timestamps.

    Returns:
        Dict[int, int]: A dictionary mapping hour (0-23) to the count of timestamps in that hour.
