import sys
from collections import Counter

def compute_median(sorted_column):
    n = len(sorted_column)
    if n % 2 == 1:
        return sorted_column[n // 2]
    else:
        return (sorted_column[n // 2 - 1] + sorted_column[n // 2]) / 2

def compute_mode(column):
    counts = Counter(column)
    max_freq = max(counts.values())
    candidates = [k for k, v in counts.items() if v == max_freq]
    return min(candidates)

def main():
    r, c = map(int, sys.stdin.readline().split())
    rows = []
    for _ in range(r):
        row = list(map(float, sys.stdin.readline().split()))
        rows.append(row)

    columns = list(zip(*rows))

    for col in columns:
        sorted_col = sorted(col)
        mean = sum(col) / r
        median = compute_median(sorted_col)
        mode = compute_mode(col)
        variance = sum((x - mean) ** 2 for x in col) / r

        print(f"{mean:.4f} {median:.4f} {mode:.4f} {variance:.4f}")

