import sys
from datetime import datetime

def is_valid_log_line(line):
    parts = line.split(' ', 3)
    if len(parts) != 4:
        return False

    date_str, time_str, level_str, message_str = parts

    try:
        datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        return False

    try:
        datetime.strptime(time_str, '%H:%M:%S')
    except ValueError:
        return False

    if level_str not in {'INFO', 'WARN', 'ERROR', 'DEBUG'}:
        return False

    if message_str.strip() == '':
        return False

    return True

