def prime_factors(n):
    n = abs(n)  # Take absolute value to handle negative numbers
    factors = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                count += 1
                n = n // i
            factors.append((i, count))
        i += 1
    if n > 1:
        factors.append((n, 1))
    return factors

def prime_factors(n):
    if n == 0:
        return []

    n = abs(n)  # Handle negative numbers
    factors = []
    divisor = 2

    while divisor * divisor <= n:
        if n % divisor == 0:
            exponent = 0
            while n % divisor == 0:
                exponent += 1
                n //= divisor
            factors.append((divisor, exponent))
        divisor += 1

    if n > 1:
        factors.append((n, 1))

    return factors

def prime_factors(n):
    if n <= 1:
        return []
    n = abs(n)
    factors = []

    # Handle 2 separately
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    if count > 0:
        factors.append((2, count))

    # Now check odd numbers from 3 upwards
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count > 0:
            factors.append((i, count))
        i += 2

    # If remaining n is greater than 1, it's a prime
    if n > 1:
        factors.append((n, 1))

    return factors

