def compute_and_update_z_scores(session: Session):
    # Group by user, compute mean and std deviation
    group_stats = (
        session.query(
            UsageRecord.user_id,
            func.avg(UsageRecord.processing_time_ms).label("mean"),
            func.stddev(UsageRecord.processing_time_ms).label("stddev")
        )
        .group_by(UsageRecord.user_id)
        .subquery()
    )

    # Update the normalized processing time using the computed group stats
    update_query = (
        session.query(UsageRecord)
        .join(group_stats, UsageRecord.user_id == group_stats.c.user_id)
        .update(
            {
                UsageRecord.normalized_processing_time:
                    (
                        (UsageRecord.processing_time_ms - group_stats.c.mean) / 
                        group_stats.c.stddev
                    )
            },
            synchronize_session=False
        )
    )

    session.commit()

