from functools import wraps

def throttle(interval_seconds=60):
    def decorator(func):
        last_run = None  # Store the last execution time

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal last_run
            current_time = time.time()

            # Allow the first call immediately
            if last_run is None or current_time - last_run >= interval_seconds:
                last_run = current_time
                return func(*args, **kwargs)

        return wrapper

    return decorator

