import sys
import threading
import os
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class FileModifiedHandler(FileSystemEventHandler):
    def __init__(self, filename, callback):
        self.filename = os.path.abspath(filename)
        self.callback = callback

    def on_modified(self, event):
        if event.src_path == self.filename:
            self.callback()


def run_callback():
    print(f"File modified: {filename}")


def monitor_file(filename):
    path_to_watch = os.path.dirname(filename)
    if not path_to_watch:
        path_to_watch = "."  # default to current directory if filename has no path

    event_handler = FileModifiedHandler(filename, run_callback)
    observer = Observer()
    observer.schedule(event_handler, path=path_to_watch, recursive=False)
    observer.start()

    try:
        while True:
            pass  # Keep running the observer
    except KeyboardInterrupt:
        observer.stop()
    observer.join()


