    # Start the file watching in a separate thread
    thread = threading.Thread(target=monitor_file, args=(filename,), daemon=True)
    thread.start()

    # Echo the remaining input
    for line in sys.stdin:
        sys.stdout.write(line)
        sys.stdout.flush()

