def prime_factors(
    n: int,
) -> str:
    """Return the prime factorisation of an integer as a string.

    Returns the factorisation in the form "2 * 3 * 5", etc.
    """
    factors = []
    # Handle division by 2
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # Check for odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2
    # If remaining n is a prime
    if n > 1:
        factors.append(n)
    return " * ".join(map(str, factors))

def prime_factors(
    n: int,
) -> list[int]:
    """Return the prime factors of the given integer.

    Returns a list of prime factors, possibly with duplicates.
    """
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

