import re

def parse_log_line(line):
    """
    Attempts to parse a single log line into a structured dictionary.
    Returns None if the line is malformed.
    """
    # Define a regex to match the timestamp, log level, and message.
    pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+\[([A-Z]+)\]\s+(.*)$'
    match = re.fullmatch(pattern, line.strip())

    if not match:
        return None  # Malformed format

    timestamp, level, message = match.groups()

    # Try to parse the message into key-value pairs
    data = {}
    key_value_parts = re.split(r'\s*,\s*', message)

    for part in key_value_parts:
        if '=' in part:
            key, value = part.split('=', 1)
            data[key.strip()] = value.strip()
        else:
            return None  # Invalid key-value pair

    return {
        'timestamp': timestamp,
        'level': level,
        'data': data
    }

def process_logs(log_lines):
    """
    Process a list of log lines, returning only those that parsed successfully.
    """
    parsed_logs = []
    for line in log_lines:
        parsed = parse_log_line(line)
        if parsed:
            parsed_logs.append(parsed)
    return parsed_logs

