    def paragraph(self, text):
        return text + '\n\n'

    def heading(self, text, level, raw):
        return text + '\n\n'

    def list_item(self, text):
        return text + '\n'

    def block_quote(self, text):
        return text + '\n\n'

    def code_block(self, text, info=None):
        return text + '\n\n'

    def table(self, text):
        return text + '\n\n'

    def text(self, text):
        return text

    def hr(self):
        return '\n\n'

    def link(self, link, text, title=None):
        return text

    def image(self, link, text, title=None):
        return text

    def strong(self, text):
        return text

    def emphasis(self, text):
        return text

    def code(self, text):
        return text

    def inline(self, children, parent, current):
