import sys
from collections import defaultdict, deque

def main():
    edges = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            continue
        u, v = parts
        edges.append((u, v))

    adj = defaultdict(list)
    in_degree = defaultdict(int)
    nodes = set()

    for u, v in edges:
        adj[v].append(u)
        in_degree[u] += 1
        nodes.add(u)
        nodes.add(v)

    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    result = []
    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(nodes):
        print("Cycle detected")
    else:
        print(' '.join(result))

