def throttle(func):
    """Decorator that limits the function to one call per minute."""
    last_call_time = [None]  # Use a list to make it mutable in the closure

    def wrapper(*args, **kwargs):
        current_time = time.time()
        if last_call_time[0] is None or (current_time - last_call_time[0]) >= 60:
            func(*args, **kwargs)
            last_call_time[0] = current_time

    return wrapper

