import math
from collections import defaultdict

def cluster_points(points, radius, min_group_size):
    """
    Clusters a list of 2D points using a density-based approach.

    Parameters:
        points (list of lists): List of 2D points in the format [[x1, y1], [x2, y2], ...].
        radius (float): Maximum distance between any two points to be in the same cluster.
        min_group_size (int): Minimum number of points required to form a cluster.

    Returns:
        list of lists: Each sublist is a cluster, containing the points in that cluster.
    """
    n = len(points)
    if n == 0:
        return []

    # Step 1: Precompute neighbors
    neighbors = [[] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j:
                dx = points[i][0] - points[j][0]
                dy = points[i][1] - points[j][1]
                dist = math.sqrt(dx * dx + dy * dy)
                if dist <= radius:
                    neighbors[i].append(j)

    # Step 2: Assign cluster labels
    labels = [-1] * n
    cluster_id = 0

    for i in range(n):
        if labels[i] == -1:
            # Check if current point is a core point (including itself)
            if len(neighbors[i]) + 1 >= min_group_size:
                queue = [i]
                labels[i] = cluster_id
                while queue:
                    current = queue.pop(0)
                    for neighbor in neighbors[current]:
                        if labels[neighbor] == -1:
                            labels[neighbor] = cluster_id
                            queue.append(neighbor)
                cluster_id += 1

    # Step 3: Group points by cluster
    clusters = defaultdict(list)
    for idx, label in enumerate(labels):
        if label != -1:
            clusters[label].append(points[idx])

    # Return as list of clusters (without using IDs)
    return list(clusters.values())

