def calculate_statistics(df: pd.DataFrame):
    """
    Calculate mean, median, mode, and variance for each numeric column in a DataFrame.

    Parameters:
        df (pd.DataFrame): The input data.

    Returns:
        dict: A dictionary with column names as keys and a dictionary of statistics as values.
              Non-numeric columns are marked with an error.
    """
    stats = {}
    for col in df.columns:
        if pd.api.types.is_numeric_dtype(df[col]):
            mean_val = df[col].mean()
            median_val = df[col].median()
            mode_val = df[col].mode().iloc[0] if not df[col].isna().all() else None
            var_val = df[col].var()

            # Optional: Handle multimodal columns by returning a list instead of first mode
            # mode_val = list(df[col].mode())

            stats[col] = {
                'mean': mean_val,
                'median': median_val,
                'mode': mode_val,
                'variance': var_val
            }
        else:
            stats[col] = {
                'error': 'Non-numeric column'
            }
    return stats

