) -> list[str]:
    """Return a valid execution order for tasks based on dependencies, raising an error if there's a cycle.

    Returns the ordered list of tasks.
    """
    graph = {}
    in_degree = {}
    nodes = set()

    for task, dep in dependencies:
        nodes.add(task)
        nodes.add(dep)

    for node in nodes:
        in_degree[node] = 0

    for task, dep in dependencies:
        if dep not in graph:
            graph[dep] = []
        graph[dep].append(task)
        in_degree[task] += 1

