import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    # Parse input into rows of columns
    rows = []
    for line in lines:
        columns = line.strip().split()
        rows.append(columns)

    num_cols = len(rows[0])
    numeric_cols = []

    # Identify numeric columns
    for col_idx in range(num_cols):
        is_numeric = True
        for row in rows:
            if len(row) <= col_idx:
                is_numeric = False
                break
            try:
                float(row[col_idx])
            except ValueError:
                is_numeric = False
                break
        if is_numeric:
            numeric_cols.append(col_idx)

    # Precompute mean and standard deviation for numeric columns
    mean_std = {}
    for col_idx in numeric_cols:
        values = [float(row[col_idx]) for row in rows]
        mean = sum(values) / len(values)
        sum_squares = sum((x - mean) ** 2 for x in values)
        std = (sum_squares / len(values)) ** 0.5
        mean_std[col_idx] = (mean, std)

    # Generate output
    for row in rows:
        new_row = []
        for col_idx in range(len(row)):
            if col_idx in mean_std:
                value = float(row[col_idx])
                mean, std = mean_std[col_idx]
                if std == 0.0:
                    new_val = 0.0
                else:
                    new_val = (value - mean) / std
                new_row.append(str(new_val))
            else:
                new_row.append(row[col_idx])
        print(' '.join(new_row))

