def main():
    # Read lines from standard input
    data = [line.strip().split() for line in sys.stdin if line.strip()]
    if not data:
        return  # No input to process

    num_cols = len(data[0])
    transformed_columns = []

    # Process each column
    for j in range(num_cols):
        column = [row[j] for row in data]
        if is_numeric_column(column):
            col_array = np.array([float(x) for x in column])
            mean = np.mean(col_array)
            std = np.std(col_array)
            if std == 0:
                # Avoid division by zero, leave as original
                transformed_col = column
            else:
                # Standardize
                transformed_col = [(x - mean) / std for x in col_array]
        else:
            transformed_col = column

        transformed_columns.append(transformed_col)

    # Reconstruct the output rows
    for i in range(len(data)):
