import sys

def main():
    # Read input lines and split into columns
    data = [line.strip().split() for line in sys.stdin if line.strip()]

    if not data:
        return  # no input

    num_rows = len(data)
    num_cols = len(data[0])

    # Identify numeric columns
    numeric_cols = []
    for j in range(num_cols):
        is_numeric = True
        for i in range(num_rows):
            try:
                float(data[i][j])
            except ValueError:
                is_numeric = False
                break
        if is_numeric:
            numeric_cols.append(j)

    # Process each numeric column
    for j in numeric_cols:
        # Extract values as floats
        values = [float(data[i][j]) for i in range(num_rows)]
        mean = sum(values) / num_rows

        # Compute population standard deviation
        variance = sum((x - mean) ** 2 for x in values) / num_rows
        std_dev = variance ** 0.5

        if std_dev == 0.0:
            # All values are identical
            for i in range(num_rows):
                data[i][j] = '0.0'
        else:
            # Replace with standardized values (x - mean) / std_dev
            for i in range(num_rows):
                standardized = (values[i] - mean) / std_dev
                data[i][j] = f"{standardized:.10f}"

    # Output the transformed table
    for row in data:
        print(' '.join(row))

if __name__ == "__main__":
    main()
